#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# pebble-relay setup: Cloudflare login → WSPC key → Destination → preflight →
# KV + wrangler.toml → deploy → secrets → Pebble app → test event → logs.
# Spec: https://github.com/yurenju/pebble-index-wspc/issues/19 (section 9).
#
# Nothing personal is kept in .env: the non-secret values live in the
# git-ignored wrangler.toml, and both secrets live only in the Worker. On a
# re-run, current wrangler.toml values are offered as defaults (seeded into a
# throwaway ENV_FILE so the library's `ask` can offer them).

WORKER_NAME="pebble-relay"
CONFIG="wrangler.toml"
EXAMPLE="wrangler.example.toml"
KV_TITLE="pebble-relay-deliveries"
WSPC_API="https://api.wspc.ai"
KEY_LABEL="pebble-relay"
DEFAULT_PATH="00-inbox/pebble-index-records.md"
DEFAULT_TZ="Asia/Tokyo"
LOGS_URL="https://dash.cloudflare.com/?to=/:account/workers/services/view/${WORKER_NAME}/production/observability/logs"

WSPC_API_KEY=""        # in memory only; never written to disk
NEW_KEY_ID=""          # id of a key created by this run (for later revocation)
KEEP_WSPC_KEY=0        # 1 = Worker already has WSPC_API_KEY and owner keeps it
KEEP_SIGNING=0         # 1 = Worker already has PEBBLE_SIGNING_SECRET and owner keeps it
PEBBLE_SIGNING_SECRET=""
WORKER_URL=""
WORK_DIR=""

wrangler() { npx --no-install wrangler "$@"; }

# toml_str KEY: the string value of `KEY = "..."` in wrangler.toml, if any.
toml_str() {
  [[ -f "$CONFIG" ]] || return 0
  sed -n "s/^${1}[[:space:]]*=[[:space:]]*\"\(.*\)\"[[:space:]]*$/\1/p" "$CONFIG" | head -n1
}

# toml_escape VALUE: escape for a TOML basic string.
toml_escape() { local v="${1//\\/\\\\}"; printf '%s' "${v//\"/\\\"}"; }

# worker_secrets: names of secrets already on the deployed Worker (empty if
# the Worker doesn't exist yet).
worker_secrets() {
  wrangler secret list --name "$WORKER_NAME" --format json 2>/dev/null \
    | jq -r '.[].name' 2>/dev/null || true
}

# wspc_get PATH: GET against the WSPC API with the in-memory key. Writes the
# body to $WORK_DIR/body and prints the HTTP status.
wspc_get() {
  curl -sS -o "$WORK_DIR/body" -w '%{http_code}' \
    -H "Authorization: Bearer $WSPC_API_KEY" "$WSPC_API$1" || printf '000'
}

# destination_content: GET the Destination file; prints the HTTP status.
destination_content() {
  local enc
  enc=$(jq -rn --arg p "$DESTINATION_PATH" '$p|@uri')
  wspc_get "/drive/libraries/${WSPC_LIBRARY_ID}/files/content?path=${enc}"
}

# list_libraries: "id<TAB>name" lines, via the in-memory key or the local
# wspc login. Empty when neither is available.
list_libraries() {
  if [[ -n "$WSPC_API_KEY" ]]; then
    local cursor="" status q
    while :; do
      q="/drive/libraries?limit=100"
      [[ -n "$cursor" ]] && q+="&cursor=$(jq -rn --arg c "$cursor" '$c|@uri')"
      status=$(wspc_get "$q")
      [[ "$status" == 200 ]] || return 0
      jq -r '.libraries[] | select(.deleted_at == null) | "\(.id)\t\(.name)"' "$WORK_DIR/body"
      cursor=$(jq -r '.next_cursor // empty' "$WORK_DIR/body")
      [[ -n "$cursor" ]] || return 0
    done
  elif command -v wspc >/dev/null 2>&1 && wspc whoami >/dev/null 2>&1; then
    wspc --json drive library ls 2>/dev/null \
      | jq -r '.libraries[] | select(.deleted_at == null) | "\(.id)\t\(.name)"' 2>/dev/null || true
  fi
}

# last_entry: last "- " line of the Destination file (empty if none/unreadable).
last_entry() {
  [[ "$(destination_content)" == 200 ]] || return 0
  grep -E '^- ' "$WORK_DIR/body" | tail -n1 || true
}

run_wizard() {

TOTAL_STAGES=11

cd "$(dirname "${BASH_SOURCE[0]}")/.."
WORK_DIR=$(mktemp -d)
TAIL_PID=""
trap 'rm -rf "$WORK_DIR"; [[ -n "$TAIL_PID" ]] && kill "$TAIL_PID" 2>/dev/null; true' EXIT

# Seed the throwaway ENV_FILE with current wrangler.toml values so `ask`
# offers them as defaults on a re-run.
ENV_FILE="$WORK_DIR/defaults.env"
{
  printf "WSPC_LIBRARY_ID='%s'\n" "$(toml_str WSPC_LIBRARY_ID | grep -v XXXX || true)"
  printf "DESTINATION_PATH='%s'\n" "$(toml_str DESTINATION_PATH)"
  printf "TIMEZONE='%s'\n" "$(toml_str TIMEZONE)"
} > "$ENV_FILE"
grep -q "^DESTINATION_PATH=''" "$ENV_FILE" && sed -i.bak "s|^DESTINATION_PATH=''|DESTINATION_PATH='$DEFAULT_PATH'|" "$ENV_FILE"
grep -q "^TIMEZONE=''" "$ENV_FILE" && sed -i.bak "s|^TIMEZONE=''|TIMEZONE='$DEFAULT_TZ'|" "$ENV_FILE"

banner "pebble-relay: deploy the Pebble → WSPC Drive Relay"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check local tools"
missing=0
for tool in curl jq openssl node npx; do
  if command -v "$tool" >/dev/null 2>&1; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$tool"
  else
    warn "$tool is missing"; missing=1
  fi
done
if command -v node >/dev/null 2>&1; then
  node_major=$(node -p 'process.versions.node.split(".")[0]')
  if (( node_major < 20 )); then warn "node $(node -v) is too old: need ≥ 20"; missing=1; fi
fi
if (( missing )); then
  say ""
  say "Install what's missing, then re-run this script:"
  note "  macOS:   brew install curl jq openssl node"
  note "  Debian:  sudo apt install curl jq openssl, and node ≥ 20 from https://nodejs.org or fnm/nvm"
  exit 1
fi
[[ -f "$EXAMPLE" ]] || { warn "$EXAMPLE not found: run this from a pebble-index-wspc checkout"; exit 1; }
if [[ ! -x node_modules/.bin/wrangler ]]; then
  say "wrangler isn't installed in this checkout yet."
  confirm "Run npm install now?" || { warn "wrangler is required; run npm install and re-run"; exit 1; }
  npm install
fi
say "wrangler $(wrangler --version 2>/dev/null | grep -Eo '[0-9]+\.[0-9]+\.[0-9]+' | head -n1)"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Log in to Cloudflare"
whoami_out=$(wrangler whoami 2>&1 || true)
if grep -q "not authenticated" <<<"$whoami_out" || {
     say "Already logged in:"
     grep -Ei 'email|account' <<<"$whoami_out" | head -n 8 | sed 's/^/  /' || true
     confirm "Log in as a different Cloudflare account instead?" && wrangler logout
   }; then
  # The default OAuth flow redirects the browser to localhost:8976, which only
  # works when the browser runs on this machine. Over SSH, in a container or a
  # remote dev box, use the device flow: open a URL anywhere and enter a code.
  if [[ -n "${SSH_CONNECTION:-}" ]] || [[ "$(uname -s)" == Linux && -z "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ]] \
     && ! command -v wslview >/dev/null 2>&1 && ! command -v explorer.exe >/dev/null 2>&1; then
    login_args=(--device)
  else
    confirm "Is your web browser on this same machine? (No = remote/SSH: log in with a code instead)" \
      && login_args=() || login_args=(--device)
  fi
  if (( ${#login_args[@]} )); then
    say "Device login: open the URL wrangler prints (on any device), log in to"
    say "Cloudflare, enter the code it shows, then click Allow."
  else
    say "wrangler will open a browser: log in to Cloudflare and click Allow."
  fi
  if ! wrangler login ${login_args[@]+"${login_args[@]}"}; then
    if (( ${#login_args[@]} )) || ! confirm "Login failed. Try the device flow (URL + code) instead?"; then
      warn "Cloudflare login failed; re-run when ready"; exit 1
    fi
    wrangler login --device || { warn "Cloudflare login failed; re-run when ready"; exit 1; }
  fi
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "WSPC API key"
say "The Worker writes to WSPC Drive with a long-lived API key. It is a root"
say "key for your whole account, so it lives only in the Worker's secrets:"
say "never in the Pebble app, never on this disk."
existing_secrets=$(worker_secrets)
if grep -qx WSPC_API_KEY <<<"$existing_secrets" && ! confirm "The Worker already has WSPC_API_KEY. Replace it?"; then
  KEEP_WSPC_KEY=1
  note "Keeping the current key. (It isn't stored locally, so the preflight check is skipped.)"
else
  if command -v wspc >/dev/null 2>&1 && wspc whoami >/dev/null 2>&1 \
     && confirm "You're logged in to the wspc CLI. Create a new key labelled '$KEY_LABEL' with it?"; then
    wspc --json keys create --label "$KEY_LABEL" > "$WORK_DIR/key.json"
    WSPC_API_KEY=$(jq -r '.api_key' "$WORK_DIR/key.json")
    NEW_KEY_ID=$(jq -r '.id' "$WORK_DIR/key.json")
    rm -f "$WORK_DIR/key.json"
    printf '  %s✓ created%s key %s (%s)\n' "$GREEN" "$RESET" "$NEW_KEY_ID" "$KEY_LABEL"
  else
    say "Create a key yourself, on any machine logged in to the wspc CLI:"
    note "  wspc keys create --label $KEY_LABEL"
    note "  (don't reuse the 'pebble-relay-test' key from the experiments)"
    ask_secret WSPC_API_KEY "Paste the api_key value:"
  fi
  [[ -n "$WSPC_API_KEY" && "$WSPC_API_KEY" != null ]] || { warn "no key captured"; exit 1; }
  status=$(wspc_get "/drive/libraries?limit=1")
  if [[ "$status" != 200 ]]; then
    warn "WSPC rejected the key (HTTP $status): $(head -c 300 "$WORK_DIR/body")"
    exit 1
  fi
  printf '  %s✓%s key accepted by WSPC\n' "$GREEN" "$RESET"
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Choose the Destination"
say "Every transcript is appended to one file. Pick its library:"
list_libraries > "$WORK_DIR/libs.tsv"
if [[ -s "$WORK_DIR/libs.tsv" ]]; then
  awk -F'\t' '{ printf "    %2d) %s  %s\n", NR, $2, $1 }' "$WORK_DIR/libs.tsv"
  ask WSPC_LIBRARY_ID "Library number or id (lib_…):"
  if [[ "$WSPC_LIBRARY_ID" =~ ^[0-9]+$ ]]; then
    WSPC_LIBRARY_ID=$(awk -F'\t' -v n="$WSPC_LIBRARY_ID" 'NR == n { print $1 }' "$WORK_DIR/libs.tsv")
  fi
else
  note "Couldn't list libraries (no key in hand and no wspc login). Type the id instead;"
  note "'wspc drive library ls' shows it."
  ask WSPC_LIBRARY_ID "Library id (lib_…):"
fi
[[ "$WSPC_LIBRARY_ID" =~ ^lib_[A-Za-z0-9]+$ ]] || { warn "'$WSPC_LIBRARY_ID' isn't a library id"; exit 1; }
say ""
say "Path of the file inside that library (created on the first write if missing)."
ask DESTINATION_PATH "Destination path:"
DESTINATION_PATH="${DESTINATION_PATH#/}"
[[ -n "$DESTINATION_PATH" ]] || { warn "path can't be empty"; exit 1; }
say ""
say "Time zone for the 'YYYY-MM-DD HH:mm' stamp on each Entry (IANA name)."
ask TIMEZONE "Time zone:"
if ! node -e 'new Intl.DateTimeFormat("en", { timeZone: process.argv[1] })' "$TIMEZONE" 2>/dev/null; then
  warn "'$TIMEZONE' isn't a valid IANA time zone"; exit 1
fi
printf '  %s✓%s %s : %s  (%s)\n' "$GREEN" "$RESET" "$WSPC_LIBRARY_ID" "$DESTINATION_PATH" "$TIMEZONE"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Preflight: can the key read the Destination?"
if [[ -z "$WSPC_API_KEY" ]]; then
  warn "Skipped: the kept key isn't available locally."
  note "If the key and library don't match, writes fail with write_failed in the logs."
else
  status=$(destination_content)
  code=$(jq -r '.error.code // empty' "$WORK_DIR/body" 2>/dev/null || true)
  if [[ "$status" == 200 ]]; then
    printf '  %s✓%s file exists (%s bytes); new Entries go at its end\n' "$GREEN" "$RESET" "$(wc -c < "$WORK_DIR/body" | tr -d ' ')"
  elif [[ "$status" == 404 && "$code" == FILE_NOT_FOUND ]]; then
    printf '  %s✓%s library reachable; file doesn'\''t exist yet and will be created on the first write\n' "$GREEN" "$RESET"
  else
    warn "Preflight failed (HTTP $status${code:+, $code}): $(head -c 300 "$WORK_DIR/body")"
    say "Check the library id and the key, then re-run this script."
    exit 1
  fi
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "KV namespace and wrangler.toml"
say "The Relay remembers each Pebble delivery id for 30 days in KV, to skip duplicates."
wrangler kv namespace list 2>/dev/null > "$WORK_DIR/kv.json" || echo '[]' > "$WORK_DIR/kv.json"
kv_id=$(toml_str id | grep -v '<' || true)
if [[ -n "$kv_id" ]] && jq -e --arg id "$kv_id" 'any(.[]; .id == $id)' "$WORK_DIR/kv.json" >/dev/null 2>&1; then
  printf '  %s✓%s reusing KV namespace %s from %s\n' "$GREEN" "$RESET" "$kv_id" "$CONFIG"
else
  kv_id=$(jq -r --arg t "$KV_TITLE" '[.[] | select(.title == $t or (.title | endswith("-" + $t)))][0].id // empty' "$WORK_DIR/kv.json" 2>/dev/null || true)
  if [[ -n "$kv_id" ]]; then
    printf '  %s✓%s reusing existing KV namespace %s (%s)\n' "$GREEN" "$RESET" "$KV_TITLE" "$kv_id"
  else
    confirm "Create KV namespace '$KV_TITLE' in your Cloudflare account?" || { warn "the Relay needs it; re-run when ready"; exit 1; }
    wrangler kv namespace create "$KV_TITLE" >/dev/null
    wrangler kv namespace list 2>/dev/null > "$WORK_DIR/kv.json"
    kv_id=$(jq -r --arg t "$KV_TITLE" '[.[] | select(.title == $t or (.title | endswith("-" + $t)))][0].id // empty' "$WORK_DIR/kv.json")
    [[ -n "$kv_id" ]] || { warn "created the namespace but couldn't find its id; run: npx wrangler kv namespace list"; exit 1; }
    printf '  %s✓ created%s KV namespace %s (%s)\n' "$GREEN" "$RESET" "$KV_TITLE" "$kv_id"
  fi
fi

git check-ignore -q "$CONFIG" 2>/dev/null || warn "$CONFIG is not git-ignored: don't commit it (this repo is public)"
LIB_V=$(toml_escape "$WSPC_LIBRARY_ID") PATH_V=$(toml_escape "$DESTINATION_PATH") \
TZ_V=$(toml_escape "$TIMEZONE") KV_V=$(toml_escape "$kv_id") awk '
  /^WSPC_LIBRARY_ID[[:space:]]*=/  { print "WSPC_LIBRARY_ID = \"" ENVIRON["LIB_V"] "\""; next }
  /^DESTINATION_PATH[[:space:]]*=/ { print "DESTINATION_PATH = \"" ENVIRON["PATH_V"] "\""; next }
  /^TIMEZONE[[:space:]]*=/         { print "TIMEZONE = \"" ENVIRON["TZ_V"] "\""; next }
  /^id[[:space:]]*=/               { print "id = \"" ENVIRON["KV_V"] "\""; next }
  { print }
' "$EXAMPLE" > "$WORK_DIR/wrangler.toml"
if [[ -f "$CONFIG" ]] && cmp -s "$CONFIG" "$WORK_DIR/wrangler.toml"; then
  printf '  %s✓%s %s already up to date\n' "$GREEN" "$RESET" "$CONFIG"
else
  if [[ -f "$CONFIG" ]]; then
    say "Changes to $CONFIG (regenerated from $EXAMPLE):"
    diff -u "$CONFIG" "$WORK_DIR/wrangler.toml" | sed 's/^/    /' || true
    confirm "Overwrite $CONFIG?" || { warn "kept the old $CONFIG; nothing deployed"; exit 1; }
  fi
  cp "$WORK_DIR/wrangler.toml" "$CONFIG"
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$CONFIG"
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Deploy the Worker"
say "Deploys '$WORKER_NAME' to <your-subdomain>.workers.dev from this checkout."
note "Secrets are set in the next stage; until then the Worker rejects every request."
confirm "Run npx wrangler deploy now?" || { warn "not deployed; re-run when ready"; exit 1; }
if ! wrangler deploy 2>&1 | tee "$WORK_DIR/deploy.log"; then
  warn "deploy failed. If it mentions a workers.dev subdomain, open the Cloudflare"
  warn "dashboard → Workers & Pages once to register one, then re-run."
  exit 1
fi
WORKER_URL=$(grep -Eo "https://${WORKER_NAME}\.[A-Za-z0-9-]+\.workers\.dev" "$WORK_DIR/deploy.log" | head -n1 || true)
if [[ -z "$WORKER_URL" ]]; then
  note "Couldn't spot the URL in wrangler's output."
  ask WORKER_URL "Worker URL (https://$WORKER_NAME.<subdomain>.workers.dev):"
fi
WORKER_URL="${WORKER_URL%/}/"
printf '  %s✓ deployed%s %s\n' "$GREEN" "$RESET" "$WORKER_URL"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Worker secrets"
existing_secrets=$(worker_secrets)
if (( KEEP_WSPC_KEY )); then
  note "WSPC_API_KEY: keeping the current one"
else
  printf '%s' "$WSPC_API_KEY" | wrangler secret put WSPC_API_KEY --name "$WORKER_NAME" >/dev/null
  printf '  %s✓ set%s WSPC_API_KEY\n' "$GREEN" "$RESET"
fi
if grep -qx PEBBLE_SIGNING_SECRET <<<"$existing_secrets" \
   && ! confirm "PEBBLE_SIGNING_SECRET is already set. Replace it? (then paste the new one into both gestures)"; then
  KEEP_SIGNING=1
  note "PEBBLE_SIGNING_SECRET: keeping the current one"
else
  PEBBLE_SIGNING_SECRET=$(openssl rand -hex 32)
  printf '%s' "$PEBBLE_SIGNING_SECRET" | wrangler secret put PEBBLE_SIGNING_SECRET --name "$WORKER_NAME" >/dev/null
  printf '  %s✓ set%s PEBBLE_SIGNING_SECRET (shown once in the next stage)\n' "$GREEN" "$RESET"
fi
say ""
say "Smoke test: an unsigned POST should be rejected with 401…"
smoke=$(curl -sS -o /dev/null -w '%{http_code}' -X POST "$WORKER_URL" || printf '000')
if [[ "$smoke" == 401 ]]; then
  printf '  %s✓%s Worker is live and checking signatures (HTTP 401)\n' "$GREEN" "$RESET"
else
  warn "expected 401, got HTTP $smoke (a fresh workers.dev URL can take a minute; check $WORKER_URL)"
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Point the Pebble app at the Relay"
say "In the Pebble app: Index 01 settings → Webhook. Do this for BOTH gestures,"
say "'Hold & talk' and 'Double click & hold':"
step "URL: ${BOLD}${WORKER_URL}${RESET}"
if (( KEEP_SIGNING )); then
  step "Sign requests: on, with the secret you pasted last time (unchanged)"
  note "  Lost it? Re-run this script and choose to replace PEBBLE_SIGNING_SECRET."
else
  step "Sign requests: on, and paste this secret:"
  printf '\n      %s%s%s\n\n' "$BOLD" "$PEBBLE_SIGNING_SECRET" "$RESET"
  warn "It's shown only this once and stored nowhere else. Lost it? Re-run and replace it."
fi
step "Send: Transcription only (no audio)"
step "No extra headers"
pause "Press Enter once both gestures are saved…"
PEBBLE_SIGNING_SECRET=""

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Send a test event"
say "Watching the Worker's live log (wrangler tail) while you send a test event."
say "The Relay answers a signed test event with 200 and writes nothing; a wrong"
say "signing secret gets 401."
note "Starting wrangler tail (takes ~10 s to connect)…"
wrangler tail "$WORKER_NAME" --format json > "$WORK_DIR/tail.json" 2>"$WORK_DIR/tail.err" &
TAIL_PID=$!
sleep 10
kill -0 "$TAIL_PID" 2>/dev/null || note "wrangler tail exited early: $(tail -n 3 "$WORK_DIR/tail.err" | tr '\n' ' ')"
step "In the Pebble app's Webhook settings, tap 'Send test event' (either gesture)."
pause "Press Enter after the app shows the result…"
sleep 3
kill "$TAIL_PID" 2>/dev/null || true; wait "$TAIL_PID" 2>/dev/null || true; TAIL_PID=""
# Tail events are (possibly pretty-printed) JSON objects; a fetch event carries
# .event.response.status. Count each status seen, e.g. "1×200".
statuses=$(jq -r '.event.response.status? // empty' "$WORK_DIR/tail.json" 2>/dev/null || true)
[[ -n "$statuses" ]] || statuses=$(grep -Eo '"status": *[0-9]{3}' "$WORK_DIR/tail.json" 2>/dev/null | grep -Eo '[0-9]{3}' || true)
seen=$(grep -E '^[0-9]{3}$' <<<"$statuses" | sort | uniq -c | awk '{ printf "%s%s×%s", (NR > 1 ? ", " : ""), $1, $2 }' || true)
if [[ -n "$seen" ]] && grep -qw 200 <<<"$statuses"; then
  printf '  %s✓%s test event accepted (HTTP 200): URL and signing secret match\n' "$GREEN" "$RESET"
elif [[ -n "$seen" ]]; then
  warn "The Worker answered: $seen"
  note "401 means the secret in the Pebble app doesn't match; re-run and replace it."
  SKIPPED+=("get a 200 for the Pebble test event")
else
  # The tail can miss requests (still connecting, proxy, …). The app's own
  # result is the ground truth.
  note "wrangler tail didn't capture the request, so go by what the app showed."
  if confirm "Did the Pebble app show 200 OK for the test event?"; then
    printf '  %s✓%s test event accepted (HTTP 200): URL and signing secret match\n' "$GREEN" "$RESET"
  else
    warn "401 → the signing secret doesn't match (re-run and replace it)."
    warn "No response / 404 → check the URL is exactly $WORKER_URL"
    SKIPPED+=("get a 200 for the Pebble test event")
  fi
fi
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Optional: record for real"
if [[ -z "$WSPC_API_KEY" ]]; then
  note "The kept key isn't available here, so this check can't read the file."
  note "Record a sentence and look at the end of $DESTINATION_PATH in WSPC Drive."
elif confirm "Record a sentence on the ring and check that it lands in the file?"; then
  before=$(last_entry)
  step "Record a short sentence with either gesture now."
  say "Waiting up to 3 minutes for a new Entry…"
  after="$before"
  for _ in $(seq 1 36); do
    sleep 5
    after=$(last_entry)
    [[ "$after" != "$before" ]] && break
  done
  if [[ "$after" != "$before" ]]; then
    printf '  %s✓%s new Entry: %s\n' "$GREEN" "$RESET" "$after"
  else
    warn "No new Entry yet. Check the logs (next screen) for write_failed."
    SKIPPED+=("confirm a real recording is appended to $DESTINATION_PATH")
  fi
fi
pause

finish
say "Relay URL:    $WORKER_URL"
say "Destination:  $WSPC_LIBRARY_ID : $DESTINATION_PATH ($TIMEZONE)"
[[ -n "$NEW_KEY_ID" ]] && say "WSPC key:     $NEW_KEY_ID ('$KEY_LABEL'); revoke with: wspc keys rm $NEW_KEY_ID"
say ""
say "When a write fails, the only notice is a log line. Check it here:"
step "Dashboard: $LOGS_URL"
step "Live:      npx wrangler tail $WORKER_NAME"
step "Filter:    event = write_failed  (the line includes the transcript text)"
warn "Workers Logs keep only 3 days."
say ""
say "Housekeeping: revoke the experiment key 'pebble-relay-test' if it still exists:"
note "  wspc keys ls   then   wspc keys rm <its key_… id>"
say ""
say "Change the Destination or a key later by re-running: scripts/setup.sh"
printf '\n'
}

run_wizard "$@"; exit
